import { createInterface } from 'node:readline';
import { pathToFileURL } from 'node:url';
import path from 'node:path';
const rootUrl = relative => pathToFileURL(path.resolve(process.cwd(), relative)).href;
const { GraphTokenScheduler } = await import(rootUrl('languages/typescript/runtimes/node/semantic-execution-graph/scheduler.js'));
const { evaluateExpression } = await import(rootUrl('languages/typescript/runtimes/node/semantic-transformation-evaluator.mjs'));
const { createSynchronousSchemaAdmission } = await import(rootUrl('languages/typescript/runtimes/node/schema-contract-admission-provider.mjs'));
const lines = createInterface({ input: process.stdin });
const stream = lines[Symbol.asyncIterator]();
const request = JSON.parse((await stream.next()).value);
const { plan, input: root, rootExecutionId } = request;
const physical = new Set(request.physicalCellIds);
const cells = new Map(plan.canonicalGraph.cells.map(cell => [cell.cellId, cell]));
const collections = new Map();
async function provider(input, context) {
  if (physical.has(context.cellId)) {
    console.log(JSON.stringify({ type: 'invoke-provider', cellId: context.cellId, cellExecutionId: context.cellExecutionId, rootExecutionId, input }));
    const reply = JSON.parse((await stream.next()).value);
    if (reply.error) throw new Error(reply.error);
    return { outcomeValue: reply.outcome };
  }
  const expression = context.configuration?.binding?.configuration?.expression ?? context.configuration;
  if (expression && typeof expression.op === 'string') {
    try {
      // The scheduler supplies the original Port input when it resumes a
      // transformation operation. Decomposed expression cells use their
      // enclosing expression input instead.
      const entering = context.configuration?.kind === 'invoke-port' ? input : context.decompositionInput ?? input;
      const outcomeValue = evaluateExpression(expression, { input: entering, root });
      if (outcomeValue === undefined) {
        const scope = expression.op === 'path' ? (expression.from ?? 'input') : null;
        if (scope === 'input' || scope === 'root') return { outcomeValue: false, outcomeVariant: 'FALSE' };
        throw new Error('LEXICAL_BINDING_NOT_AVAILABLE_AT_CELL_ALTITUDE');
      }
      if (['map', 'flat-map', 'filter', 'find', 'some', 'every'].includes(expression.op)) {
        const occurrence = collections.get(context.cellId) ?? 0;
        collections.set(context.cellId, occurrence + 1);
        const source = expression.from ? evaluateExpression(expression.from, { input: entering, root }) : [];
        return { outcomeValue, outcomeVariant: occurrence < (Array.isArray(source) ? source.length : 0) ? 'CONTINUE' : 'STOP' };
      }
      return { outcomeValue };
    } catch {
      return { outcomeValue: input, outcomeVariant: 'VALUE' };
    }
  }
  if (cells.get(context.cellId).execution.authorityId === 'mechanic:identity.v1') return { outcomeValue: input, outcomeVariant: 'VALUE' };
  throw new Error('UNDECLARED_EXECUTION_MECHANIC:' + context.cellId);
}
const authorities = new Map(plan.bindingAuthorities.map(authority => [authority.id, authority]));
const admission = createSynchronousSchemaAdmission(plan.contractCatalog);
const result = await new GraphTokenScheduler(plan.canonicalGraph, plan.realizationOverlay, {
  providers: Object.fromEntries(plan.realizationOverlay.providerBindings.map(binding => [binding.providerProfileId, provider])),
  rootExecutionId,
  admitContract: (contractId, value) => admission.admits(contractId, value),
  projectBinding: (id, input) => evaluateExpression(authorities.get(id).binding.configuration.expression, { input, root })
}).execute(root);
console.log(JSON.stringify({ type: 'result', result }));
lines.close();
process.stdin.destroy();
